{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MAPLEMONK.PLAETO_DB_PRODUCT_MARKETING_CONSOLIDATED AS SELECT CAST(Adset_Name AS STRING) AS ADSET_NAME, CAST(Adset_ID AS STRING) AS ADSET_ID, CAST(ad_id AS STRING) AS AD_ID, CAST(ad_name AS STRING) AS AD_NAME, CAST(Account_Name AS STRING) AS ACCOUNT_NAME, CAST(Account_ID AS STRING) AS ACCOUNT_ID, CAST(Campaign_Name AS STRING) AS CAMPAIGN_NAME, CAST(Campaign_ID AS STRING) AS CAMPAIGN_ID, COALESCE(FC.product_id,SC.product_id) AS PRODUCT_ID, CAST(SC.VARIANT_ID AS STRING) AS VARIANT_ID, CAST(Date AS DATE) AS DATE, CAST(NULL AS STRING) AS AD_TYPE, CAST(NULL AS STRING) AS AD_STRENGTH, CAST(NULL AS STRING) AS AD_NETWORK_TYPE, CAST(NULL AS STRING) AS AD_FINAL_URL, FORMAT_DATE(\'%A\', Date) AS DAY_OF_WEEK, EXTRACT(YEAR FROM Date) AS YEAR, EXTRACT(MONTH FROM Date) AS MONTH, CAST(Channel AS STRING) AS Channel, CAST(Account AS STRING) AS ACCOUNT, CAST(Clicks AS FLOAT64) AS CLICKS, CAST(Spend AS FLOAT64) AS SPEND, CAST(Impressions AS FLOAT64) AS IMPRESSIONS, CAST(Conversions AS FLOAT64) AS CONVERSIONS, CAST(Conversion_Value AS FLOAT64) AS CONVERSION_VALUE, CAST(Product_Category AS STRING) AS PRODUCT_CATEGORY, CAST(PS.SALES AS FLOAT64) AS SALES FROM maplemonk.Plaeto_db_Product_FACEBOOK_CONSOLIDATED fc LEFT JOIN ( SELECT PRODUCT_ID, VARIANT_ID, Product_Category FROM maplemonk.plaeup_wh_SHOPIFY_FACT_ITEMS QUALIFY ROW_NUMBER() OVER (PARTITION BY VARIANT_ID ORDER BY Product_Category) = 1 ) sc ON fc.PRODUCT_ID = sc.VARIANT_ID LEFT JOIN ( SELECT order_date, product_id, SUM(IFNULL(selling_price,0)) AS Sales FROM maplemonk.plaeup_wh_sales_consolidated GROUP BY 1,2 ) ps ON CAST(fc.product_id AS STRING) = CAST(ps.product_id AS STRING) AND CAST(fc.Date AS DATE) = ps.order_date UNION ALL SELECT CAST(ADSET_NAME AS STRING) AS ADSET_NAME, CAST(ADSET_ID AS STRING) AS ADSET_ID, CAST(AD_ID AS STRING) AS AD_ID, CAST(AD_NAME AS STRING) AS AD_NAME, CAST(ACCOUNT_NAME AS STRING) AS ACCOUNT_NAME, CAST(ACCOUNT_ID AS STRING) AS ACCOUNT_ID, CAST(CAMPAIGN_NAME AS STRING) AS CAMPAIGN_NAME, CAST(CAMPAIGN_ID AS STRING) AS CAMPAIGN_ID, CAST(SPLIT(segments_product_item_id, \'_\')[SAFE_OFFSET(2)] AS STRING) AS product_id, CAST(SPLIT(segments_product_item_id, \'_\')[SAFE_OFFSET(3)] AS STRING) AS variant_id, CAST(DATE AS DATE) AS DATE, CAST(AD_TYPE AS STRING) AS AD_TYPE, CAST(AD_STRENGTH AS STRING) AS AD_STRENGTH, CAST(AD_NETWORK_TYPE AS STRING) AS AD_NETWORK_TYPE, CAST(AD_FINAL_URL AS STRING) AS AD_FINAL_URL, CAST(DAY_OF_WEEK AS STRING) AS DAY_OF_WEEK, CAST(YEAR AS INT64) AS YEAR, CAST(MONTH AS INT64) AS MONTH, CAST(Channel AS STRING) AS Channel, CAST(ACCOUNT AS STRING) AS ACCOUNT, CAST(clicks AS FLOAT64) AS CLICKS, CAST(spend AS FLOAT64) AS SPEND, CAST(Impressions AS FLOAT64) AS IMPRESSIONS, CAST(Conversions AS FLOAT64) AS CONVERSIONS, CAST(Conversion_Value AS FLOAT64) AS CONVERSION_VALUE, CAST (Product_Category AS STRING) AS PRODUCT_CATEGORY, CAST(VS.SALES AS FLOAT64) AS SALES FROM maplemonk.Plaeto_db_Product_GOOGLEADS_CONSOLIDATED GC LEFT JOIN ( SELECT PRODUCT_ID, VARIANT_ID, Product_Category FROM maplemonk.plaeup_wh_SHOPIFY_FACT_ITEMS QUALIFY ROW_NUMBER() OVER (PARTITION BY PRODUCT_ID ORDER BY Product_Category) = 1 ) sc ON CAST(SPLIT(segments_product_item_id, \'_\')[SAFE_OFFSET(2)] AS STRING) = sc.PRODUCT_ID LEFT JOIN ( SELECT order_date, variant_id, SUM(IFNULL(selling_price,0)) AS Sales FROM maplemonk.plaeup_wh_sales_consolidated GROUP BY 1,2 ) vs ON CAST(SPLIT(gc.segments_product_item_id, \'_\')[SAFE_OFFSET(3)] AS STRING) = CAST(vs.variant_id AS STRING) AND CAST(gc.Date AS DATE) = vs.order_date;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            